//! Disposable benchmark of existing String indexed operations.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::{size, Oop};
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let integer = h.named(b"Integer").unwrap();
    let gc = h.named(b"GC").unwrap();
    let zero = q.call(integer, b"fromWord:", &[size(0).unwrap()]).unwrap();
    let eight = q.call(integer, b"fromWord:", &[size(8).unwrap()]).unwrap();
    q.call(gc, b"automaticCollection:", &[size(0).unwrap()]).unwrap();
    let cases: &[(&[u8], &[Oop])] = &[(b"byteAt:", &[zero]), (b"at:", &[zero]), (b"copyFrom:to:", &[zero, eight])];
    for length in [64, 4096, 1048576] {
        let text = q.string(&vec![b'x'; length]).unwrap();
        let calls = if length == 1048576 { 5000 } else { 20000 };
        for &(name, args) in cases {
            let selector = q.keep(h.intern(name).unwrap()).unwrap();
            for _ in 0..100 { unsafe { h.id.send(text, selector, args).unwrap(); } }
            for _ in 0..5 {
                q.call(gc, b"collectPrecisely", &[]).unwrap();
                let mut last = text;
                let start = unsafe { clock_gettime_nsec_np(16) };
                for _ in 0..calls { last = unsafe { h.id.send(text, selector, args).unwrap() }; }
                let elapsed = unsafe { clock_gettime_nsec_np(16) } - start;
                if name == b"byteAt:" {
                    let word = q.call(integer, b"wordOf:", &[last]).unwrap();
                    assert_eq!(q.word_bits(word).unwrap(), usize::from(b'x'));
                } else {
                    let bytes = q.call(last, b"bytes", &[]).unwrap();
                    assert_eq!(q.read_bytes(bytes).unwrap(), vec![b'x'; if name == b"at:" {1} else {8}]);
                }
                println!("{length} {} {calls} {elapsed}", String::from_utf8_lossy(name));
            }
        }
    }
}
